window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-403fc82aebd1b536"]={"versions": [{"id": "FIG-403fc82aebd1b536", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E Profile 11. Das Diagramm modelliert einen atomaren Ausführungsschritt der E2E-End-to-End-Kommunikationsabsicherung zur Extraktion des Sequenzzählers aus empfangenen Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflusseinstieg.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy nibble from bit-position Config-&gt;CounterOffset in Data in Little Endian order to uint8 local variable ReceivedCounter</code>.\n</li><li><strong>Kommentar-Notiz</strong>: Zugeordneter Erläuterungsvermerk mit Berechnungsformeln zur Bit- und Byte-Adressierung:\n<ul class=\"fig-list\"><li><code>Byte position in data array can be obtained by: Byte = Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>\n</li><li><code>Nibble within byte can be obtained by: Counter = (Byte &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>\n</li></ul>\n</li><li><strong>Endknoten</strong>: Aktivitätsendknoten nach Abschluss der Extraktion.\n</li><li><strong>Kontext / Parameter</strong>:\n<ul class=\"fig-list\"><li>Konfigurationsstruktur <code>Config</code> mit Element <code>CounterOffset</code> (Bit-Offset).\n</li><li>Byte-Array <code>Data</code> (Array empfangener Datenbytes in Little-Endian-Bitreihenfolge).\n</li><li>Lokale Ergebnisvariable <code>ReceivedCounter</code> vom Datentyp <code>uint8</code> (4-Bit-Nibble).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft linear und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten wird die Aktion zur Zählerextraktion betreten.\n</li><li>Anhand des Bit-Offsets <code>Config-&gt;CounterOffset</code> wird das entsprechende Byte im Puffer <code>Data</code> indexiert (<code>&gt;&gt; 3</code>).\n</li><li>Aus dem adressierten Byte wird das 4-Bit-Nibble an die lokale Variable <code>ReceivedCounter</code> übergeben.\n</li><li>Der Ablauf terminiert unmittelbar am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normativ verbindliche Verhalten gemäß Anforderung <code>[PRS_E2E_00518]</code>. Implementierer müssen beachten, dass die im angehängten Kommentar angegebene Bitshift-Formel einen Links-Shift (<code>&lt;&lt;</code>) enthält (<code>(Byte &lt;&lt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>), was bei der Ausrichtung eines Nibbles innerhalb eines Bytes mathematisch/logisch zu einem Überlauf bzw. fehlerhaften Bits führen kann, sofern das Nibble nicht an Bitposition 0 beginnt. Die Hauptanweisung verlangt Little-Endian-Bitordnung beim Auslesen des 4-Bit-Zählers aus dem Byte-Array <code>Data</code>.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1720fe091b3f2cf9", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E Profile 11. Das Diagramm modelliert einen atomaren Ausführungsschritt der E2E-End-to-End-Kommunikationsabsicherung zur Extraktion des Sequenzzählers aus empfangenen Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflusseinstieg.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy nibble from bit-position Config-&gt;CounterOffset in Data in Little Endian order to uint8 local variable ReceivedCounter</code>.\n</li><li><strong>Kommentar-Notiz</strong>: Zugeordneter Erläuterungsvermerk mit Berechnungsformeln zur Bit- und Byte-Adressierung:\n<ul class=\"fig-list\"><li><code>Byte position in data array can be obtained by: Byte = Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>\n</li><li><code>Nibble within byte can be obtained by: Counter = (Byte &gt;&gt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>\n</li></ul>\n</li><li><strong>Endknoten</strong>: Aktivitätsendknoten nach Abschluss der Extraktion.\n</li><li><strong>Kontext / Parameter</strong>:\n<ul class=\"fig-list\"><li>Konfigurationsstruktur <code>Config</code> mit Element <code>CounterOffset</code> (Bit-Offset).\n</li><li>Byte-Array <code>Data</code> (Array empfangener Datenbytes in Little-Endian-Bitreihenfolge).\n</li><li>Lokale Ergebnisvariable <code>ReceivedCounter</code> vom Datentyp <code>uint8</code> (4-Bit-Nibble).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft linear und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten wird die Aktion zur Zählerextraktion betreten.\n</li><li>Anhand des Bit-Offsets <code>Config-&gt;CounterOffset</code> wird das entsprechende Byte im Puffer <code>Data</code> indexiert (<code>&gt;&gt; 3</code>).\n</li><li>Aus dem adressierten Byte wird das 4-Bit-Nibble an die lokale Variable <code>ReceivedCounter</code> übergeben.\n</li><li>Der Ablauf terminiert unmittelbar am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normativ verbindliche Verhalten gemäß Anforderung <code>[PRS_E2E_00518]</code>. Zur Implementierung der Zählerextraktion wird in der Kommentar-Notiz die korrigierte Extraktionsformel mit Rechts-Shift (<code>&gt;&gt;</code>) spezifiziert: Das adressierte Byte <code>Data[Config-&gt;CounterOffset &gt;&gt; 3]</code> wird um <code>(Config-&gt;CounterOffset &amp; 0x7)</code> Bits nach rechts verschoben und mit Maske <code>0xF</code> auf das 4-Bit-Nibble reduziert. Der Zähler wird in Little-Endian-Reihenfolge in die Variable <code>ReceivedCounter</code> übernommen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-38a34640e84c5df0", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E Profile 11. Das Diagramm modelliert einen atomaren Ausführungsschritt der E2E-End-to-End-Kommunikationsabsicherung zur Extraktion des Sequenzzählers aus empfangenen Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflusseinstieg.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy nibble from bit-position Config-&gt;CounterOffset in Data in Little Endian order to uint8 local variable ReceivedCounter</code>.\n</li><li><strong>Kommentar-Notiz</strong>: Zugeordneter Erläuterungsvermerk mit Berechnungsformeln zur Bit- und Byte-Adressierung:\n<ul class=\"fig-list\"><li><code>Byte position in data array can be obtained by: Byte = Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>\n</li><li><code>Nibble within byte can be obtained by: Counter = (Byte &gt;&gt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>\n</li></ul>\n</li><li><strong>Endknoten</strong>: Aktivitätsendknoten nach Abschluss der Extraktion.\n</li><li><strong>Kontext / Parameter</strong>:\n<ul class=\"fig-list\"><li>Konfigurationsstruktur <code>Config</code> mit Element <code>CounterOffset</code> (Bit-Offset).\n</li><li>Byte-Array <code>Data</code> (Array empfangener Datenbytes in Little-Endian-Bitreihenfolge).\n</li><li>Lokale Ergebnisvariable <code>ReceivedCounter</code> vom Datentyp <code>uint8</code> (4-Bit-Nibble).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft linear und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten wird die Aktion zur Zählerextraktion betreten.\n</li><li>Anhand des Bit-Offsets <code>Config-&gt;CounterOffset</code> wird das entsprechende Byte im Puffer <code>Data</code> indexiert (<code>&gt;&gt; 3</code>).\n</li><li>Aus dem adressierten Byte wird das 4-Bit-Nibble an die lokale Variable <code>ReceivedCounter</code> übergeben.\n</li><li>Der Ablauf terminiert unmittelbar am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normativ verbindliche Verhalten gemäß Anforderung <code>[PRS_E2E_00518]</code>. Zur Implementierung der Zählerextraktion wird in der Kommentar-Notiz die korrigierte Extraktionsformel mit Rechts-Shift (<code>&gt;&gt;</code>) spezifiziert: Das adressierte Byte <code>Data[Config-&gt;CounterOffset &gt;&gt; 3]</code> wird um <code>(Config-&gt;CounterOffset &amp; 0x7)</code> Bits nach rechts verschoben und mit Maske <code>0xF</code> auf das 4-Bit-Nibble reduziert. Der Zähler wird in Little-Endian-Reihenfolge in die Variable <code>ReceivedCounter</code> übernommen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1d5cbb8365a93f24", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des Funktionsschritts „Read Counter“ innerhalb der Prüffunktion <code>E2E_P11Check()</code> des AUTOSAR E2E Profile 11. Das Diagramm modelliert einen atomaren Ausführungsschritt der E2E-End-to-End-Kommunikationsabsicherung zur Extraktion des Sequenzzählers aus empfangenen Nutzdaten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Startknoten</strong>: Initialer Kontrollflusseinstieg.\n</li><li><strong>Aktionsknoten</strong>: <code>Copy nibble from bit-position Config-&gt;CounterOffset in Data in Little Endian order to uint8 local variable ReceivedCounter</code>.\n</li><li><strong>Kommentar-Notiz</strong>: Zugeordneter Erläuterungsvermerk mit Berechnungsformeln zur Bit- und Byte-Adressierung:\n<ul class=\"fig-list\"><li><code>Byte position in data array can be obtained by: Byte = Data[Config-&gt;CounterOffset &gt;&gt; 3]</code>\n</li><li><code>Nibble within byte can be obtained by: Counter = (Byte &gt;&gt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>\n</li></ul>\n</li><li><strong>Endknoten</strong>: Aktivitätsendknoten nach Abschluss der Extraktion.\n</li><li><strong>Kontext / Parameter</strong>:\n<ul class=\"fig-list\"><li>Konfigurationsstruktur <code>Config</code> mit Element <code>CounterOffset</code> (Bit-Offset).\n</li><li>Byte-Array <code>Data</code> (Array empfangener Datenbytes in Little-Endian-Bitreihenfolge).\n</li><li>Lokale Ergebnisvariable <code>ReceivedCounter</code> vom Datentyp <code>uint8</code> (4-Bit-Nibble).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft linear und unkonditioniert:</p>\n<ol class=\"fig-list\"><li>Ausgehend vom Startknoten wird die Aktion zur Zählerextraktion betreten.\n</li><li>Anhand des Bit-Offsets <code>Config-&gt;CounterOffset</code> wird das entsprechende Byte im Puffer <code>Data</code> indexiert (<code>&gt;&gt; 3</code>).\n</li><li>Aus dem adressierten Byte wird das 4-Bit-Nibble an die lokale Variable <code>ReceivedCounter</code> übergeben.\n</li><li>Der Ablauf terminiert unmittelbar am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Aktivität definiert das normativ verbindliche Verhalten gemäß Anforderung <code>[PRS_E2E_00518]</code>. Zur Implementierung der Zählerextraktion wird in der Kommentar-Notiz die korrigierte Extraktionsformel mit Rechts-Shift (<code>&gt;&gt;</code>) spezifiziert: Das adressierte Byte <code>Data[Config-&gt;CounterOffset &gt;&gt; 3]</code> wird um <code>(Config-&gt;CounterOffset &amp; 0x7)</code> Bits nach rechts verschoben und mit Maske <code>0xF</code> auf das 4-Bit-Nibble reduziert. Der Zähler wird in Little-Endian-Reihenfolge in die Variable <code>ReceivedCounter</code> übernommen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-403fc82aebd1b536", "to": "FIG-1720fe091b3f2cf9", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kommentar-Notiz (<code>Byte position in data array...</code>): In der Formel zur Extraktion des Nibbles wurde der Shift-Operator von Links-Shift (<code>&lt;&lt;</code>) zu Rechts-Shift (<code>&gt;&gt;</code>) korrigiert (<code>Counter = (Byte &gt;&gt; (Config-&gt;CounterOffset &amp; 0x7)) &amp; 0xF</code>).\n</li></ul>"}, {"from": "FIG-1720fe091b3f2cf9", "to": "FIG-38a34640e84c5df0", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Gesamtes Diagramm: Skalierung bzw. Rendering neu erzeugt (Bildgröße von 789x319 auf 750x304 Pixel verringert), ohne inhaltliche Änderungen an Elementen oder Texten.\n</li></ul>"}, {"from": "FIG-38a34640e84c5df0", "to": "FIG-1d5cbb8365a93f24", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
